import cpmpy as cp
import json

model = cp.Model()

# Decision Variables
x = cp.intvar(1, 40, shape=9, name='x')

# All oranges in different bowls and sorted order
model += cp.AllDifferent(x)
for i in range(8):
    model += x[i] < x[i+1]

# No three-term arithmetic progression constraints
for i in range(9):
    for j in range(i+1, 9):
        for k in range(j+1, 9):
            model += (x[i] + x[k] != 2 * x[j])

# Solve and print solution
if model.solve():
    solution = {'x': x.value().tolist()}
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
